INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 12, 'theory', 'Quiz: classes');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 12, 0, 'class Dog: pass; d = Dog(). What is d?', '["The class Dog", "An instance (object) of the class Dog", "A function", "A class attribute"]', 1, 'A class is a blueprint, and d is an object made from it: an instance of the class Dog.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 12, 1, 'When does Python call the __init__ method?', '["When the object is deleted", "On every call of any method", "Automatically when an instance is created", "Only if you call it by hand"]', 2, '__init__ is the constructor: Python itself calls it on Dog(...) and passes in the arguments from the parentheses.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 12, 2, 'a = Counter(); b = a; b.inc(). What happened to the counter a?', '["Unchanged: b is a copy", "Increased: a and b are the same object", "Python raised an error", "A third counter was created"]', 1, 'Assignment does not copy the object: a single instance just got a second name.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 12, 3, 'class A: items = []. x, y = A(), A(); x.items.append(1). What is y.items?', '["[]", "[1]", "None", "An error"]', 1, 'The list is declared at the class level, so it is shared by all instances. Create mutable data in __init__.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 12, 4, 'What happens on A().hello() if the method is defined as def hello(): ... (without self)?', '["Everything works", "TypeError: the method got an extra argument", "NameError", "Python adds self by itself"]', 1, 'Python passes the object as the first argument, but the definition has no parameter for it.');
